        // store 里 `read()` 调的是那个对象 → TypeError，设置页永远显示
        // 「读取模型目录失败：e is not a function」（2026-11-03 现场，压缩后的名字）。
        const catalog = createAcpCatalogStore(catalogReaderOf(ctx));
        const report = (msg) => say(`acp visibility: ${msg}`);
